// Module-level variable simulates a database row for a single user.
// In a real app this would be a DB query (e.g. Prisma, Drizzle, etc.).
let notificationsEnabled = false;

export function getNotificationPreference(): boolean {
  return notificationsEnabled;
}

export function toggleNotificationPreference(): void {
  notificationsEnabled = !notificationsEnabled;
}

