import { getNotificationPreference } from './store';
import { toggleNotifications } from './actions';

export default function Home() {
  const enabled = getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently: <strong>{enabled ? 'ON' : 'OFF'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'OFF' : 'ON'}
        </button>
      </form>
    </main>
  );
}

